using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(b =>
        {
            // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type" in EF Core 9.
            // Fix: Keep the old property name so existing documents are still found.
            b.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: Id format changed from "Blog|<key>" to just "<key>" in EF Core 9.
            // Fix: Revert to legacy format so existing documents with "Blog|1" ids still resolve.
            b.HasPartitionKey(e => e.Id);
            b.Property(e => e.Id).ToJsonProperty("id");
            b.UseIdProperty();
        });

        // Breaking change 3: HasIndex throws at runtime for Cosmos provider in EF Core 9.
        // Removed the unsupported HasIndex call.
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

