using Microsoft.EntityFrameworkCore;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Breaking change 4: Sync I/O now throws by default.
        // Fix: suppress until migrated to async, or migrate to async (preferred).
        optionsBuilder.ConfigureWarnings(w => w.Ignore(
            Microsoft.EntityFrameworkCore.Diagnostics.CosmosEventId.SyncNotSupported));
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(b =>
        {
            // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type".
            // Fix: explicitly keep the old JSON property name for existing documents.
            b.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: id no longer includes the discriminator (was "Blog|1", now just "1").
            // Fix: opt back into the legacy format for existing documents.
            b.HasDiscriminatorInJsonId();

            // Breaking change 3: Key property now maps to JSON "id" directly (shadow id removed).
            // Fix: restore the shadow id property so existing documents with separate "Id" still work.
            b.HasShadowId();
        });

        // Breaking change 5: HasIndex() now throws for the Cosmos provider.
        // Fix: removed the unsupported HasIndex call.
        // (was: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);)
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

